"""Read-only hardware diagnostics via the existing authenticated remote proxy."""
from ui_layout import apply
PAGE=r'''<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hardware</title><style>
.hw-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:12px}.hw-grid section{min-width:0}.hw-row{display:flex;justify-content:space-between;align-items:start;gap:12px;border-top:1px solid var(--border);padding:8px 0}.hw-row span:last-child{text-align:right;overflow-wrap:anywhere;max-width:65%}.hw-row span:first-child{color:var(--muted)}.hw-actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.hw-actions select{flex:1;min-width:150px}.hw-note{font-size:13px;color:var(--muted)}.hw-sub{padding:10px;border:1px solid var(--border);border-radius:8px;margin:8px 0}.hw-sub h3{margin:0 0 8px}pre{white-space:pre-wrap;overflow-wrap:anywhere}
.hw-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.hw-tabs button[aria-pressed=true]{outline:2px solid currentColor}.hw-grid section[hidden]{display:none}.hw-ports{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.hw-port{border:1px solid var(--border);border-radius:8px;padding:12px;text-align:center}.hw-jack{width:48px;height:30px;border:3px solid currentColor;border-radius:4px;margin:8px auto;background:repeating-linear-gradient(90deg,transparent 0 4px,currentColor 4px 5px,transparent 5px 6px);opacity:.8}.hw-up{color:#16a34a}.hw-down{color:var(--muted)}.hw-meter{width:100%;height:12px}</style></head><body><main><h1>Hardware</h1><p>Hardwarediagnostik</p><nav></nav>
<section class="card"><div class="hw-actions"><label for="controller">Controller</label><select id="controller"></select><button id="refresh">Opdater</button><button id="export" disabled>Eksportér JSON</button></div><p id="status" role="status">Indlæser…</p><p class="hw-note">Kun metadata, som er tilgængelige i appens container. Valgfri aktiv JEDEC/SFDP-identifikation. Ingen hukommelsesindhold eller krypteringsnøgler udlæses.</p></section>
<div class="hw-tabs" id="tabs"></div><label><input type="checkbox" id="auto" checked> Automatisk opdatering (10 s)</label><div class="hw-grid" id="cards"></div>
<script>
const $=id=>document.getElementById(id);let controllers=[],last=null,busy=false,tab="System";
const groups={"Hardwareidentifikation":"System","Systemressourcer":"System","Bootloader":"System","SPI – enhedsmetadata":"SPI","Kryptering / LUKS":"Lager","Partitioner":"Lager","eMMC":"Lager","RTC":"RTC","Ethernet-switch KSZ8795CLX":"Ethernet","Netværksstatistik":"Ethernet","Watchdog":"Watchdog","STM32 / UART":"DALI","Hardwarehændelser":"DALI"};
function filter(){for(const s of $("cards").children)s.hidden=tab!=="Alle"&&s.dataset.group!==tab;for(const b of $("tabs").children)b.setAttribute("aria-pressed",String(b.textContent===tab));}
for(const name of ["System","Ethernet","SPI","Lager","RTC","Watchdog","DALI","Alle"]){const b=document.createElement("button");b.textContent=name;b.onclick=()=>{tab=name;filter();};$("tabs").append(b);}filter();
function el(tag,t){const e=document.createElement(tag);if(t!==undefined)e.textContent=String(t);return e;}
function row(parent,k,v){const r=el("div");r.className="hw-row";r.append(el("span",k),el("span",v==null?"Ikke tilgængelig":typeof v==="object"?JSON.stringify(v):v===true?"Ja":v===false?"Nej":v));parent.append(r);}
function card(title,note){const s=el("section");s.className="card";s.dataset.group=groups[title]||"System";s.append(el("h2",title));if(note){const p=el("p",note);p.className="hw-note";s.append(p);}$("cards").append(s);return s;}
function sub(p,name){const s=el("div");s.className="hw-sub";s.append(el("h3",name));p.append(s);return s;}
function fields(p,data,labels){for(const [k,label] of Object.entries(labels))row(p,label,data?.[k]);}
const mb=x=>Number.isFinite(x)?(x/1048576).toFixed(0)+" MiB":null;
function render(s){$("cards").replaceChildren();
let a=card("Hardwareidentifikation");row(a,"Profil",s.hardware_profile);fields(a,s.identity,{model:"Model",serial:"Serienummer",revision:"Revision",hardware:"Hardware",machine:"Arkitektur",kernel:"Kernel"});if(s.hardware_error)row(a,"Hardwarefejl",s.hardware_error);
a=card("SPI – enhedsmetadata",s.spi?.note);for(const d of s.spi?.devices||[]){const x=sub(a,d.device);fields(x,d,{bus:"Bus",chip_select:"Chip select",driver:"Driver",modalias:"Modalias",device_node:"Linux-enhed",node_visible:"Enhed synlig"});}if(!s.spi?.devices?.length)a.append(el("p","Ingen SPI-enheder synlige."));const id=s.spi?.identification||{};const ident=sub(a,"Aktiv chipidentifikation");const labels={disabled:"Deaktiveret eller ikke Vertex G4",identified:"Gyldigt JEDEC-svar",device_missing:"SPI-enhed mangler",permission_denied:"Adgang afvist",open_failed:"Kan ikke åbne SPI",no_valid_id:"Intet gyldigt JEDEC ID",unstable_response:"Ustabilt svar",communication_error:"Kommunikationsfejl"};row(ident,"Status",labels[id.status]||id.status);fields(ident,id,{device:"Enhed",speed_hz:"Hastighed (Hz)",mode:"SPI mode",jedec_id:"JEDEC ID",manufacturer:"Producent",family:"Chipfamilie",memory_type:"Hukommelsestype",capacity_code:"Kapacitetskode",sfdp_status:"SFDP-status",sfdp_revision:"SFDP-version",capacity_mismatch:"Kapacitetsafvigelse"});row(ident,"JEDEC kapacitet",mb(id.jedec_capacity_bytes));row(ident,"SFDP kapacitet",mb(id.sfdp_capacity_bytes));row(a,"Chipindhold","Ikke aflæst");row(a,"Nøglemateriale","Ikke indsamlet");
a=card("Kryptering / LUKS",s.storage?.note);for(const d of s.storage?.encryption||[]){const x=sub(a,d.device);fields(x,d,{status:"Status",version:"LUKS-version",uuid:"UUID",cipher_name:"Cipher",cipher_mode:"Mode",ciphers:"Cipher (LUKS2)",key_bits:"Nøglelængde (bit)",key_bits_reported:"Rapporterede keyslot-størrelser",keyslots:"Keyslots",kdf:"KDF"});}if(!s.storage?.encryption?.length)a.append(el("p","Ingen læsbare LUKS-metadata fundet. Det er ikke bevis for manglende kryptering."));
a=card("Partitioner",s.storage?.scope);for(const d of s.storage?.partitions||[]){const x=sub(a,d.name);row(x,"Størrelse",mb(d.bytes));fields(x,d,{partition:"Partitionsnummer",read_only:"Read-only (kernel)",block_node_visible:"Blokenhed synlig",mapping:"Mapping"});}
a=card("eMMC","Rå JEDEC-levetidsindikatorer, ikke en målt restlevetid.");for(const d of s.emmc||[]){const x=sub(a,d.device);fields(x,d,{name:"Navn",revision:"Revision",life_time_raw:"Life time A/B",pre_eol_raw:"Pre-EOL"});}if(!s.emmc?.length)a.append(el("p","Ikke tilgængelig."));
a=card("RTC","Batteriets tilstand måles ikke.");for(const d of s.rtc||[]){const x=sub(a,d.device);fields(x,d,{name:"Driver",date:"Dato",time:"Tid",hctosys:"System clock source",offset_s:"Afvigelse (s)"});}if(!s.rtc?.length)a.append(el("p","Ingen synlig RTC."));
a=card("Ethernet-switch KSZ8795CLX","Skrivebeskyttet. Venstre/højre verificeret ved kabeltest.");fields(a,s.ethernet,{status:"Status",device:"SPI",family_id:"Family ID",chip_id:"Chip ID",revision:"Revision",switch_started:"Aktiv"});const ports=s.ethernet?.ports||[];const grid=el("div");grid.className="hw-ports";a.append(grid);for(const n of [2,3]){const d=ports.find(p=>p.port===n);const x=el("div");x.className="hw-port";x.append(el("h3",n===2?"Venstre LAN":"Højre LAN"));const jack=el("div");jack.className="hw-jack "+(d?.link?"hw-up":"hw-down");x.append(jack,el("p",d==null?"Ikke tilgængelig":d.link?"Online":"Offline"));fields(x,d,{port:"PHY",speed_mbps:"Mbit/s",duplex:"Duplex",autoneg_done:"Autonegotiation"});grid.append(x);}const detail=el("details");detail.append(el("summary","Interne / øvrige PHY"));for(const d of ports.filter(p=>p.port!==2&&p.port!==3)){const x=sub(detail,d.label||"PHY "+d.port);fields(x,d,{link:"Link",speed_mbps:"Mbit/s",duplex:"Duplex"});}a.append(detail);const hist=sub(a,"Linkhistorik");for(const h of (s.ethernet?.history||[]).slice().reverse())row(hist,new Date(h.timestamp*1000).toLocaleString("da-DK"),h.label+" · "+(h.link?"Online":"Offline"));
a=card("Netværksstatistik","Linux-interface, ikke switchens fysiske porttællere.");const virtual=el("details");virtual.append(el("summary","Virtuelle netværksinterfaces"));a.append(virtual);for(const d of s.network||[]){const x=sub(/^(veth|docker|hassio|br-|tun|tap)/.test(d.interface)?virtual:a,d.interface);fields(x,d,{rx_bytes:"RX bytes",tx_bytes:"TX bytes",rx_packets:"RX pakker",tx_packets:"TX pakker",rx_errors:"RX fejl",tx_errors:"TX fejl",rx_crc_errors:"CRC fejl",rx_dropped:"RX tabt",tx_dropped:"TX tabt"});}
a=card("Watchdog","Kun status; ingen overtagelse.");for(const d of s.watchdog||[]){const x=sub(a,d.device);fields(x,d,{identity:"Driver",state:"Status",timeout_s:"Timeout (s)",timeleft_s:"Tid tilbage (s)",bootstatus:"Bootstatus",nowayout:"Nowayout"});}
a=card("Bootloader","Kun synlige Device Tree metadata.");fields(a,s.bootloader,{version:"Version","build-timestamp":"Build timestamp",capabilities:"Capabilities"});
a=card("Systemressourcer","Host-/container-synlige værdier, ikke nødvendigvis appens eget forbrug.");const r=s.resources||{};row(a,"CPU",r.cpu_percent==null?null:r.cpu_percent+" %");row(a,"Load",r.load_average);row(a,"RAM total",mb(r.visible_memory?.total));row(a,"RAM tilgængelig",mb(r.visible_memory?.available));row(a,"Data disk brugt",mb(r.data_disk?.used));row(a,"Data disk total",mb(r.data_disk?.total));row(a,"Oppetid (s)",r.host_uptime_s);for(const t of s.thermal||[])row(a,t.type||t.zone,Number(t.temperature_c).toFixed(1)+" °C");
a=card("STM32 / UART","Seneste eksisterende busstatus og transporttællere; ingen aktiv probing.");for(const b of ["1","2","3"]){const x=sub(a,"DALI "+b);fields(x,s.buses?.[b],{online:"Online",uart_ready:"UART klar",firmware:"Firmware",device:"Enhed",last_error:"Seneste fejl"});fields(x,s.transactions?.[b],{transactions:"Telegramtransaktioner",exceptions:"Transportfejl",max_ms:"Maks. svartid (ms)"});}
a=card("Hardwarehændelser","Seneste 100 observerede busstatusændringer, nulstilles ved genstart.");for(const h of (s.history||[]).slice().reverse())row(a,new Date(h.timestamp*1000).toLocaleString("da-DK"),"DALI "+h.bus+" · online "+h.online+" · UART "+h.uart_ready);if(!s.history?.length)a.append(el("p","Ingen registrerede statusændringer."));filter();
}
async function req(path,data){const base=location.pathname.replace(/\/hardware\/?$/,"/").replace(/[^/]*$/,"");const r=await fetch(base+path,{method:data===undefined?"GET":"POST",headers:{"Content-Type":"application/json"},body:data===undefined?undefined:JSON.stringify(data),cache:"no-store"});const j=await r.json();if(!r.ok||j.ok===false)throw Error(j.error||"HTTP "+r.status);return j;}
async function load(){if(busy)return;busy=true;$("controller").disabled=true;$("refresh").disabled=true;$("export").disabled=true;last=null;$("cards").replaceChildren();try{const c=controllers.find(x=>x.id===$("controller").value);if(!c)throw Error("Vælg controller");const id=c.remote_controller_id||c.controller_id;const s=c.id==="local"?await req("api/admin/hardware"):await req("api/lab/remote",{registry_id:c.id,controller_id:id,operation:"hardware"});if(s.controller_id!==id)throw Error("Controller-ID ændret");if(s.pending){$("status").textContent="Første måling afventer. Tryk Opdater igen.";return;}last=s;render(s);$("status").textContent=c.name+" · målt "+new Date(s.sampled_at*1000).toLocaleString("da-DK");$("export").disabled=false;}catch(e){$("status").textContent=String(e);}finally{busy=false;$("controller").disabled=false;$("refresh").disabled=false;}}
$("refresh").onclick=load;$("controller").onchange=()=>{localStorage.setItem("pulsar_active_controller",$("controller").value);load();};$("export").onclick=()=>{if(!last)return;const u=URL.createObjectURL(new Blob([JSON.stringify(last,null,2)],{type:"application/json"}));const a=el("a");a.href=u;a.download="pulsar-hardware.json";a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
(async()=>{try{const j=await req("api/controllers");controllers=[j.local,...j.controllers].filter(Boolean);for(const c of controllers)$("controller").add(new Option(c.name||c.id,c.id));const saved=localStorage.getItem("pulsar_active_controller");if(controllers.some(c=>c.id===saved))$("controller").value=saved;await load();}catch(e){$("status").textContent=String(e);}})();
setInterval(()=>{if($("auto").checked&&!document.hidden&&controllers.length&&!busy)load();},10000);
</script></main></body></html>'''
def page():return apply(PAGE,"hardware")
